function isolatedConfig(string $name): ?array
{
    $dsn=(string)getenv($name);
    if($dsn==='' || !preg_match('/dbname=([^;]+)/i',$dsn,$m) || !str_ends_with(strtolower($m[1]),'_test')) return null;
    $prefix=str_replace('_DSN','',$name);
    return [$dsn,(string)(getenv($prefix.'_USER')?:'root'),(string)(getenv($prefix.'_PASS')?:''),$m[1]];
}
