$coreConfig=isolatedConfig('SCHOOL_SALES_CATALOG_CORE_TEST_DSN');
if($paymentConfig===null||$coreConfig===null){echo "NOT RUN: isolated School Sales Catalog Payment/Core *_test DSNs are not configured. No database write was attempted.\n";exit(0);}
[$paymentDsn,$paymentUser,$paymentPass]=$paymentConfig;[$coreDsn,$coreUser,$corePass]=$coreConfig;
$payment=new PDO($paymentDsn,$paymentUser,$paymentPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$core=new PDO($coreDsn,$coreUser,$corePass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$paymentDb=(string)$payment->query('SELECT DATABASE()')->fetchColumn();$coreDb=(string)$core->query('SELECT DATABASE()')->fetchColumn();
