foreach($required as $table){$q=$payment->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');$q->execute([$table]);if(!(int)$q->fetchColumn())throw new RuntimeException("Missing isolated test table: $table");}
