final class CatalogIntegrationScopeProvider implements SchoolSalesApplicabilityScopeProvider {public function isCanonicalProgram(string $v):bool{return $v==='BSIT';}public function isCanonicalYearLevel(string $v):bool{return in_array($v,['1','2','3','4'],true);}public function isCanonicalProgramYear(string $p,string $y):bool{return $p==='BSIT'&&$this->isCanonicalYearLevel($y);}}
$checks=0;$tag='C'.strtoupper(bin2hex(random_bytes(5)));$ids=['items'=>[],'categories'=>[],'types'=>[]];
function ccheck(bool $ok,string $message):void{global $checks;$checks++;if(!$ok)throw new RuntimeException("Assertion failed: $message");}
function cid():string{return CatalogCorrelationId::generate();}
function actor():array{return ['user_id'=>990001,'user_name'=>'Catalog Integration','role_key'=>'accounting_admin','permissions'=>['school_sales.catalog.manage','school_sales.catalog.activate'],'ip_address'=>'127.0.0.1','user_agent'=>'MariaDB integration'];}
function runRace(string $action,array $left,array $right):array{$worker=__DIR__.'/helpers/payment-school-sales-concurrency-worker.php';$start=microtime(true)+.35;$processes=[];foreach([$left,$right]as$p){$cmd=[PHP_BINARY,$worker,$action,base64_encode(json_encode($p,JSON_THROW_ON_ERROR)),(string)$start];$proc=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);if(!is_resource($proc))throw new RuntimeException('Unable to start concurrency worker.');$processes[]=['proc'=>$proc,'pipes'=>$pipes];}$results=[];foreach($processes as$entry){$raw=stream_get_contents($entry['pipes'][1]);$err=stream_get_contents($entry['pipes'][2]);fclose($entry['pipes'][1]);fclose($entry['pipes'][2]);$exit=proc_close($entry['proc']);if($exit!==0)throw new RuntimeException("Concurrency worker failed: $err");$results[]=json_decode($raw,true,512,JSON_THROW_ON_ERROR);}return$results;}
function oneSuccess(array $race):bool{return count(array_filter($race,fn($r)=>$r['ok']))===1;}
function service(PDO $p,?PDO $c):SchoolSalesCatalogService{$writer=$c?new StructuredActivityAuditWriter($c):null;return new SchoolSalesCatalogService($p,new SchoolSalesCatalogMutationInfrastructure($p,new PaymentAuditOutboxService($p,$writer)),new CatalogIntegrationScopeProvider());}
function itemData(string $code,int $category,int $type,string $mode='ALL'):array{return ['item_code'=>$code,'item_name'=>$code,'sale_category_id'=>$category,'sale_item_type_id'=>$type,'description'=>'Concurrency fixture','applicability_mode'=>$mode];}
function priceData(string $from,?string $to=null,string $amount='100.00'):array{return ['amount'=>$amount,'currency'=>'PHP','effective_from'=>$from,'effective_to'=>$to];}
